document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("statHomeRecords"),e=document.getElementById("statHomeCountries"),a=document.getElementById("statHomeCategories");t&&(t.dataset.count=IRWR_RECORDS.length),e&&(e.dataset.count=new Set(IRWR_RECORDS.map(t=>t.country).filter(Boolean)).size),a&&(a.dataset.count=IRWR.CATEGORIES.length);const n=document.getElementById("catalogGrid");if(!n)return;const s=IRWR_RECORDS.filter(t=>t.featured);n.innerHTML=s.map((t,e)=>`\n    <div class="ccard reveal in" data-id="${IRWR.escapeHtml(t.id)}">\n      <div class="cph"><img class="photo" src="${IRWR.photoUrl(t,"",700,700)}" alt="${IRWR.escapeHtml(t.title)}" loading="${e<3?"eager":"lazy"}" width="700" height="700"></div>\n      <div class="ctags"><span class="ctag">${IRWR.escapeHtml(t.category)}</span><span class="ctag">Verified</span></div>\n      <div class="cbottom">\n        <h3>${IRWR.escapeHtml(t.title)}</h3>\n        <p>${IRWR.escapeHtml(t.description)}</p>\n        <div class="crow"><a href="holders.html?holder=${encodeURIComponent(t.holderName)}" class="btn-line">Holder profile</a><button type="button" class="btn-gold" data-ripple data-view-entry>View entry</button></div>\n      </div>\n    </div>\n  `).join(""),n.addEventListener("click",t=>{if(t.target.closest("a"))return;const e=t.target.closest(".ccard");if(!e)return;const a=IRWR.byId(e.dataset.id);a&&IRWR.openRecordModal(a)})});